.refs && _f.refs[0] && action(_f.refs[0], key) && !abortEarly) {\n          return true;\n        } else if (_f.ref && action(_f.ref, _f.name) && !abortEarly) {\n          return true;\n        } else {\n          if (iterateFieldsByAction(field, action)) {\n            break;\n          }\n        }\n      } else if (isObject(field) || Array.isArray(field)) {\n        if (iterateFieldsByAction(field as FieldRefs, action)) {\n          break;\n        }\n      }\n    }\n  }\n  return;\n};\nexport default iterateFieldsByAction;\n","import { ROOT_ERROR_TYPE } from '../constants';\nimport type {\n  FieldError,\n  FieldErrors,\n  FieldValues,\n  InternalFieldName,\n} from '../types';\nimport get from '../utils/get';\nimport set from '../utils/set';\n\nexport default <T extends FieldValues = FieldValues>(\n  errors: FieldErrors<T>,\n  error: Partial<Record<string, FieldError>>,\n  name: InternalFieldName,\n): FieldErrors<T> => {\n  const existingErrors = get(errors, name);\n  const fieldArrayErrors = Array.isArray(existingErrors) ? existingErrors : [];\n  set(fieldArrayErrors, ROOT_ERROR_TYPE, error[name]);\n  set(errors, name, fieldArrayErrors);\n  return errors;\n};\n","import type { EmptyObject } from '../types';\n\nimport isObject from './isObject';\n\nexport default (value: unknown): value is EmptyObject =>\n  isObject(value) && !Object.keys(value).length;\n","import isWeb from './isWeb';\n\nexport default (value: unknown): value is HTMLElement => {\n  if (!isWeb) {\n    return false;\n  }\n\n  const owner = value ? ((value as HTMLElement).ownerDocument as Document) : 0;\n  return (\n    value instanceof\n    (owner && owner.defaultView ? owner.defaultView.HTMLElement : HTMLElement)\n  );\n};\n","import type { FieldElement } from '../types';\n\nexport default (element: FieldElement): element is HTMLInputElement =>\n  element.type === 'radio';\n","export default (value: unknown): value is RegExp => value instanceof RegExp;\n","import type {\n  InternalFieldErrors,\n  InternalFieldName,\n  ValidateResult,\n} from '../types';\n\nexport default (\n  name: InternalFieldName,\n  validateAllFieldCriteria: boolean,\n  errors: InternalFieldErrors,\n  type: string,\n  message: ValidateResult,\n) =>\n  validateAllFieldCriteria\n    ? {\n        ...errors[name],\n        types: {\n          ...(errors[name] && errors[name]!.types ? errors[name]!.types : {}),\n          [type]: message || true,\n        },\n      }\n    : {};\n","import isUndefined from '../utils/isUndefined';\n\ntype CheckboxFieldResult = {\n  isValid: boolean;\n  value: string | string[] | boolean | undefined;\n};\n\nconst defaultResult: CheckboxFieldResult = {\n  value: false,\n  isValid: false,\n};\n\nconst validResult = { value: true, isValid: true };\n\nexport default (options?: HTMLInputElement[]): CheckboxFieldResult => {\n  if (Array.isArray(options)) {\n    if (options.length > 1) {\n      const values = options\n        .filter((option) => option && option.checked && !option.disabled)\n        .map((option) => option.value);\n      return { value: values, isValid: !!values.length };\n    }\n\n    return options[0].checked && !options[0].disabled\n      ? // @ts-expect-error expected to work in the browser\n        options[0].attributes && !isUndefined(options[0].attributes.value)\n        ? isUndefined(options[0].value) || options[0].value === ''\n          ? validResult\n          : { value: options[0].value, isValid: true }\n        : validResult\n      : defaultResult;\n  }\n\n  return defaultResult;\n};\n","type RadioFieldResult = {\n  isValid: boolean;\n  value: number | string | null;\n};\n\nconst defaultReturn: RadioFieldResult = {\n  isValid: false,\n  value: null,\n};\n\nexport default (options?: HTMLInputElement[]): RadioFieldResult =>\n  Array.isArray(options)\n    ? options.reduce(\n        (previous, option): RadioFieldResult =>\n          option && option.checked && !option.disabled\n            ? {\n                isValid: true,\n                value: option.value,\n              }\n            : previous,\n        defaultReturn,\n      )\n    : defaultReturn;\n","import type { FieldError, Ref, ValidateResult } from '../types';\nimport isBoolean from '../utils/isBoolean';\nimport isString from '../utils/isString';\n\nexport default function getValidateError(\n  result: ValidateResult,\n  ref: Ref,\n  type = 'validate',\n): FieldError | void {\n  if (\n    isString(result) ||\n    (Array.isArray(result) && result.every(isString)) ||\n    (isBoolean(result) && !result)\n  ) {\n    return {\n      type,\n      message: isString(result) ? result : '',\n      ref,\n    };\n  }\n}\n","import type { ValidationRule } from '../types';\nimport isObject from '../utils/isObject';\nimport isRegex from '../utils/isRegex';\n\nexport default (validationData?: ValidationRule) =>\n  isObject(validationData) && !isRegex(validationData)\n    ? validationData\n    : {\n        value: validationData,\n        message: '',\n      };\n","import { INPUT_VALIDATION_RULES } from '../constants';\nimport type {\n  Field,\n  FieldError,\n  FieldValues,\n  InternalFieldErrors,\n  InternalNameSet,\n  MaxType,\n  Message,\n  MinType,\n  NativeFieldValue,\n} from '../types';\nimport get from '../utils/get';\nimport isBoolean from '../utils/isBoolean';\nimport isCheckBoxInput from '../utils/isCheckBoxInput';\nimport isDateObject from '../utils/isDateObject';\nimport isEmptyObject from '../utils/isEmptyObject';\nimport isFileInput from '../utils/isFileInput';\nimport isFunction from '../utils/isFunction';\nimport isHTMLElement from '../utils/isHTMLElement';\nimport isNullOrUndefined from '../utils/isNullOrUndefined';\nimport isObject from '../utils/isObject';\nimport isRadioInput from '../utils/isRadioInput';\nimport isRegex from '../utils/isRegex';\nimport isString from '../utils/isString';\nimport isUndefined from '../utils/isUndefined';\n\nimport appendErrors from './appendErrors';\nimport getCheckboxValue from './getCheckboxValue';\nimport getRadioValue from './getRadioValue';\nimport getValidateError from './getValidateError';\nimport getValueAndMessage from './getValueAndMessage';\n\nexport default async <T extends FieldValues>(\n  field: Field,\n  disabledFieldNames: InternalNameSet,\n  formValues: T,\n  validateAllFieldCriteria: boolean,\n  shouldUseNativeValidation?: boolean,\n  isFieldArray?: boolean,\n): Promise<InternalFieldErrors> => {\n  const {\n    ref,\n    refs,\n    required,\n    maxLength,\n    minLength,\n    min,\n    max,\n    pattern,\n    validate,\n    name,\n    valueAsNumber,\n    mount,\n  } = field._f;\n  const inputValue: NativeFieldValue = get(formValues, name);\n  if (!mount || disabledFieldNames.has(name)) {\n    return {};\n  }\n  const inputRef: HTMLInputElement = refs ? refs[0] : (ref as HTMLInputElement);\n  const setCustomValidity = (message?: string | boolean) => {\n    if (shouldUseNativeValidation && inputRef.reportValidity) {\n      const validityMessage = isBoolean(message) ? '' : message || '';\n      if (refs) {\n        refs.forEach((ref) => ref.setCustomValidity(validityMessage));\n      } else {\n        inputRef.setCustomValidity(validityMessage);\n      }\n      inputRef.reportValidity();\n    }\n  };\n  const error: InternalFieldErrors = {};\n  const isRadio = isRadioInput(ref);\n  const isCheckBox = isCheckBoxInput(ref);\n  const isRadioOrCheckbox = isRadio || isCheckBox;\n  const isEmpty =\n    ((valueAsNumber || isFileInput(ref)) &&\n      isUndefined(ref.value) &&\n      isUndefined(inputValue)) ||\n    (isHTMLElement(ref) && ref.value === '') ||\n    inputValue === '' ||\n    (Array.isArray(inputValue) && !inputValue.length);\n  const appendErrorsCurry = appendErrors.bind(\n    null,\n    name,\n    validateAllFieldCriteria,\n    error,\n  );\n  const getMinMaxMessage = (\n    exceedMax: boolean,\n    maxLengthMessage: Message,\n    minLengthMessage: Message,\n    maxType: MaxType = INPUT_VALIDATION_RULES.maxLength,\n    minType: MinType = INPUT_VALIDATION_RULES.minLength,\n  ) => {\n    const message = exceedMax ? maxLengthMessage : minLengthMessage;\n    error[name] = {\n      type: exceedMax ? maxType : minType,\n      message,\n      ref,\n      ...appendErrorsCurry(exceedMax ? maxType : minType, message),\n    };\n  };\n\n  if (\n    isFieldArray\n      ? !Array.isArray(inputValue) || !inputValue.length\n      : required &&\n        ((!isRadioOrCheckbox && (isEmpty || isNullOrUndefined(inputValue))) ||\n          (isBoolean(inputValue) && !inputValue) ||\n          (isCheckBox && !getCheckboxValue(refs).isValid) ||\n          (isRadio && !getRadioValue(refs).isValid))\n  ) {\n    const { value, message } = isString(required)\n      ? { value: !!required, message: required }\n      : getValueAndMessage(required);\n\n    if (value) {\n      error[name] = {\n        type: INPUT_VALIDATION_RULES.required,\n        message,\n        ref: inputRef,\n        ...appendErrorsCurry(INPUT_VALIDATION_RULES.required, message),\n      };\n      if (!validateAllFieldCriteria) {\n        setCustomValidity(message);\n        return error;\n      }\n    }\n  }\n\n  if (!isEmpty && (!isNullOrUndefined(min) || !isNullOrUndefined(max))) {\n    let exceedMax;\n    let exceedMin;\n    const maxOutput = getValueAndMessage(max);\n    const minOutput = getValueAndMessage(min);\n\n    if (\n      !isNullOrUndefined(inputValue) &&\n      !isDateObject(inputValue) &&\n      !isNaN(inputValue as number)\n    ) {\n      const valueNumber =\n        (ref as HTMLInputElement).valueAsNumber ||\n        (inputValue ? +inputValue : inputValue);\n      if (!isNullOrUndefined(maxOutput.value)) {\n        exceedMax = valueNumber > maxOutput.value;\n      }\n      if (!isNullOrUndefined(minOutput.value)) {\n        exceedMin = valueNumber < minOutput.value;\n      }\n    } else {\n      const valueDate =\n        (ref as HTMLInputElement).valueAsDate || new Date(inputValue as string);\n      const convertTimeToDate = (time: unknown) =>\n        new Date(new Date().toDateString() + ' ' + time);\n      const isTime = ref.type == 'time';\n      const isWeek = ref.type == 'week';\n\n      if (isString(maxOutput.value) && inputValue) {\n        exceedMax = isTime\n          ? convertTimeToDate(inputValue) > convertTimeToDate(maxOutput.value)\n          : isWeek\n            ? inputValue > maxOutput.value\n            : valueDate > new Date(maxOutput.value);\n      }\n\n      if (isString(minOutput.value) && inputValue) {\n        exceedMin = isTime\n          ? convertTimeToDate(inputValue) < convertTimeToDate(minOutput.value)\n          : isWeek\n            ? inputValue < minOutput.value\n            : valueDate < new Date(minOutput.value);\n      }\n    }\n\n    if (exceedMax || exceedMin) {\n      getMinMaxMessage(\n        !!exceedMax,\n        maxOutput.message,\n        minOutput.message,\n        INPUT_VALIDATION_RULES.max,\n        INPUT_VALIDATION_RULES.min,\n      );\n      if (!validateAllFieldCriteria) {\n        setCustomValidity(error[name]!.message);\n        return error;\n      }\n    }\n  }\n\n  if (\n    (maxLength || minLength) &&\n    !isEmpty &&\n    (isString(inputValue) || (isFieldArray && Array.isArray(inputValue)))\n  ) {\n    const maxLengthOutput = getValueAndMessage(maxLength);\n    const minLengthOutput = getValueAndMessage(minLength);\n    const exceedMax =\n      !isNullOrUndefined(maxLengthOutput.value) &&\n      inputValue.length > +maxLengthOutput.value;\n    const exceedMin =\n      !isNullOrUndefined(minLengthOutput.value) &&\n      inputValue.length < +minLengthOutput.value;\n\n    if (exceedMax || exceedMin) {\n      getMinMaxMessage(\n        exceedMax,\n        maxLengthOutput.message,\n        minLengthOutput.message,\n      );\n      if (!validateAllFieldCriteria) {\n        setCustomValidity(error[name]!.message);\n        return error;\n      }\n    }\n  }\n\n  if (pattern && !isEmpty && isString(inputValue)) {\n    const { value: patternValue, message } = getValueAndMessage(pattern);\n\n    if (isRegex(patternValue) && !inputValue.match(patternValue)) {\n      error[name] = {\n        type: INPUT_VALIDATION_RULES.pattern,\n        message,\n        ref,\n        ...appendErrorsCurry(INPUT_VALIDATION_RULES.pattern, message),\n      };\n      if (!validateAllFieldCriteria) {\n        setCustomValidity(message);\n        return error;\n      }\n    }\n  }\n\n  if (validate) {\n    if (isFunction(validate)) {\n      const result = await validate(inputValue, formValues);\n      const validateError = getValidateError(result, inputRef);\n\n      if (validateError) {\n        error[name] = {\n          ...validateError,\n          ...appendErrorsCurry(\n            INPUT_VALIDATION_RULES.validate,\n            validateError.message,\n          ),\n        };\n        if (!validateAllFieldCriteria) {\n          setCustomValidity(validateError.message);\n          return error;\n        }\n      }\n    } else if (isObject(validate)) {\n      let validationResult = {} as FieldError;\n\n      for (const key in validate) {\n        if (!isEmptyObject(validationResult) && !validateAllFieldCriteria) {\n          break;\n        }\n\n        const validateError = getValidateError(\n          await validate[key](inputValue, formValues),\n          inputRef,\n          key,\n        );\n\n        if (validateError) {\n          validationResult = {\n            ...validateError,\n            ...appendErrorsCurry(key, validateError.message),\n          };\n\n          setCustomValidity(validateError.message);\n\n          if (validateAllFieldCriteria) {\n            error[name] = validationResult;\n          }\n        }\n      }\n\n      if (!isEmptyObject(validationResult)) {\n        error[name] = {\n          ref: inputRef,\n          ...validationResult,\n        };\n        if (!validateAllFieldCriteria) {\n          return error;\n        }\n      }\n    }\n  }\n\n  setCustomValidity(true);\n  return error;\n};\n","export default <T>(value: T) => (Array.isArray(value) ? value : [value]);\n","import convertToArrayPayload from './convertToArrayPayload';\n\nexport default <T>(data: T[], value: T | T[]): T[] => [\n  ...data,\n  ...convertToArrayPayload(value),\n];\n","export default <T>(value: T | T[]): undefined[] | undefined =>\n  Array.isArray(value) ? value.map(() => undefined) : undefined;\n","import convertToArrayPayload from './convertToArrayPayload';\n\nexport default function insert<T>(data: T[], index: number): (T | undefined)[];\nexport default function insert<T>(\n  data: T[],\n  index: number,\n  value: T | T[],\n): T[];\nexport default function insert<T>(\n  data: T[],\n  index: number,\n  value?: T | T[],\n): (T | undefined)[] {\n  return [\n    ...data.slice(0, index),\n    ...convertToArrayPayload(value),\n    ...data.slice(index),\n  ];\n}\n","import isUndefined from './isUndefined';\n\nexport default <T>(\n  data: (T | undefined)[],\n  from: number,\n  to: number,\n): (T | undefined)[] => {\n  if (!Array.isArray(data)) {\n    return [];\n  }\n\n  if (isUndefined(data[to])) {\n    data[to] = undefined;\n  }\n  data.splice(to, 0, data.splice(from, 1)[0]);\n\n  return data;\n};\n","import convertToArrayPayload from './convertToArrayPayload';\n\nexport default <T>(data: T[], value: T | T[]): T[] => [\n  ...convertToArrayPayload(value),\n  ...convertToArrayPayload(data),\n];\n","export default <TValue>(value: TValue[]) =>\n  Array.isArray(value) ? value.filter(Boolean) : [];\n","import compact from './compact';\nimport convertToArrayPayload from './convertToArrayPayload';\nimport isUndefined from './isUndefined';\n\nfunction removeAtIndexes<T>(data: T[], indexes: number[]): T[] {\n  let i = 0;\n  const temp = [...data];\n\n  for (const index of indexes) {\n    temp.splice(index - i, 1);\n    i++;\n  }\n\n  return compact(temp).length ? temp : [];\n}\n\nexport default <T>(data: T[], index?: number | number[]): T[] =>\n  isUndefined(index)\n    ? []\n    : removeAtIndexes(\n        data,\n        (convertToArrayPayload(index) as number[]).sort((a, b) => a - b),\n      );\n","export default <T>(data: T[], indexA: number, indexB: number): void => {\n  [data[indexA], data[indexB]] = [data[indexB], data[indexA]];\n};\n","import { PROTOTYPE_KEYWORDS } from '../constants';\n\nimport isEmptyObject from './isEmptyObject';\nimport isKey from './isKey';\nimport isNullOrUndefined from './isNullOrUndefined';\nimport isObject from './isObject';\nimport isString from './isString';\nimport isUndefined from './isUndefined';\nimport stringToPath from './stringToPath';\n\nfunction baseGet(object: any, updatePath: (string | number)[]) {\n  const length = updatePath.length - 1;\n  let index = 0;\n\n  while (index < length) {\n    if (isNullOrUndefined(object)) {\n      object = undefined;\n      break;\n    }\n    object = object[updatePath[index]];\n    index++;\n  }\n\n  return object;\n}\n\nfunction isEmptyArray(obj: unknown[]) {\n  for (const key in obj) {\n    if (obj.hasOwnProperty(key) && !isUndefined(obj[key])) {\n      return false;\n    }\n  }\n  return true;\n}\n\nexport default function unset(object: any, path: string | (string | number)[]) {\n  if (isString(path) && Object.prototype.hasOwnProperty.call(object, path)) {\n    delete object[path];\n    return object;\n  }\n\n  const paths = Array.isArray(path)\n    ? path\n    : isKey(path)\n      ? [path]\n      : stringToPath(path);\n  if (paths.some((segment) => PROTOTYPE_KEYWORDS.includes(String(segment)))) {\n    return object;\n  }\n  const childObject = paths.length === 1 ? object : baseGet(object, paths);\n\n  const index = paths.length - 1;\n  const key = paths[index];\n\n  if (childObject) {\n    delete childObject[key];\n  }\n\n  if (\n    index !== 0 &&\n    ((isObject(childObject) && isEmptyObject(childObject)) ||\n      (Array.isArray(childObject) && isEmptyArray(childObject)))\n  ) {\n    unset(object, paths.slice(0, -1));\n  }\n\n  return object;\n}\n","export default <T>(fieldValues: T[], index: number, value: T) => {\n  fieldValues[index] = value;\n  return fieldValues;\n};\n","import React from 'react';\n\nimport generateId from './logic/generateId';\nimport getFocusFieldName from './logic/getFocusFieldName';\nimport getValidationModes from './logic/getValidationModes';\nimport isWatched from './logic/isWatched';\nimport iterateFieldsByAction from './logic/iterateFieldsByAction';\nimport updateFieldArrayRootError from './logic/updateFieldArrayRootError';\nimport validateField from './logic/validateField';\nimport appendAt from './utils/append';\nimport cloneObject from './utils/cloneObject';\nimport convertToArrayPayload from './utils/convertToArrayPayload';\nimport fillEmptyArray from './utils/fillEmptyArray';\nimport get from './utils/get';\nimport insertAt from './utils/insert';\nimport isBoolean from './utils/isBoolean';\nimport isEmptyObject from './utils/isEmptyObject';\nimport isObject from './utils/isObject';\nimport moveArrayAt from './utils/move';\nimport prependAt from './utils/prepend';\nimport removeArrayAt from './utils/remove';\nimport set from './utils/set';\nimport swapArrayAt from './utils/swap';\nimport unset from './utils/unset';\nimport updateAt from './utils/update';\nimport { VALIDATION_MODE } from './constants';\nimport type {\n  Control,\n  Field,\n  FieldArray,\n  FieldArrayMethodProps,\n  FieldArrayPath,\n  FieldArrayWithId,\n  FieldError,\n  FieldErrors,\n  FieldPath,\n  FieldValues,\n  FormState,\n  InternalFieldName,\n  RegisterOptions,\n  UseFieldArrayProps,\n  UseFieldArrayReturn,\n} from './types';\nimport { useFormControlContext } from './useFormControlContext';\nimport { useIsomorphicLayoutEffect } from './useIsomorphicLayoutEffect';\n\n/**\n * A custom hook that exposes convenient methods to perform operations with a list of dynamic inputs that need to be appended, updated, removed etc. • [Demo](https://codesandbox.io/s/react-hook-form-usefieldarray-ssugn) • [Video](https://youtu.be/4MrbfGSFY2A)\n *\n * @remarks\n * [API](https://react-hook-form.com/docs/usefieldarray) • [Demo](https://codesandbox.io/s/react-hook-form-usefieldarray-ssugn)\n *\n * @param props - useFieldArray props\n *\n * @returns methods - functions to manipulate with the Field Arrays (dynamic inputs) {@link UseFieldArrayReturn}\n *\n * @example\n * ```tsx\n * function App() {\n *   const { register, control, handleSubmit, reset, trigger, setError } = useForm({\n *     defaultValues: {\n *       test: []\n *     }\n *   });\n *   const { fields, append } = useFieldArray({\n *     control,\n *     name: \"test\"\n *   });\n *\n *   return (\n *     <form onSubmit={handleSubmit(data => console.log(data))}>\n *       {fields.map((item, index) => (\n *          <input key={item.id} {...register(`test.${index}.firstName`)}  />\n *       ))}\n *       <button type=\"button\" onClick={() => append({ firstName: \"bill\" })}>\n *         append\n *       </button>\n *       <input type=\"submit\" />\n *     </form>\n *   );\n * }\n * ```\n */\nexport function useFieldArray<\n  TFieldValues extends FieldValues = FieldValues,\n  TFieldArrayName extends FieldArrayPath<TFieldValues> =\n    FieldArrayPath<TFieldValues>,\n  TKeyName extends string = 'id',\n  TTransformedValues = TFieldValues,\n>(\n  props: UseFieldArrayProps<\n    TFieldValues,\n    TFieldArrayName,\n    TKeyName,\n    TTransformedValues\n  >,\n): UseFieldArrayReturn<TFieldValues, TFieldArrayName, TKeyName> {\n  const formControl = useFormControlContext<\n    TFieldValues,\n    any,\n    TTransformedValues\n  >();\n  const {\n    control = formControl,\n    name,\n    keyName = 'id',\n    disabled,\n    shouldUnregister,\n    rules,\n  } = props;\n  const [fields, setFields] = React.useState(control._getFieldArray(name));\n  const ids = React.useRef<string[]>(\n    control._getFieldArray(name).map(generateId),\n  );\n\n  const _actioned = React.useRef(false);\n\n  if (!disabled) {\n    control._names.array.add(name);\n  }\n\n  React.useMemo(\n    () =>\n      !disabled &&\n      rules &&\n      fields.length >= 0 &&\n      (control as Control<TFieldValues, any, TTransformedValues>).register(\n        name as FieldPath<TFieldValues>,\n        rules as RegisterOptions<TFieldValues>,\n      ),\n    [control, name, fields.length, rules, disabled],\n  );\n\n  useIsomorphicLayoutEffect(() => {\n    if (disabled) {\n      return;\n    }\n\n    return control._subjects.array.subscribe({\n      next: ({\n        values,\n        name: fieldArrayName,\n      }: {\n        values?: FieldValues;\n        name?: InternalFieldName;\n      }) => {\n        if (fieldArrayName === name || !fieldArrayName) {\n          const fieldValues = get(values, name);\n          if (Array.isArray(fieldValues)) {\n            setFields(fieldValues);\n            ids.current = fieldValues.map(generateId);\n          } else if (!fieldArrayName) {\n            setFields([]);\n            ids.current = [];\n          }\n        }\n      },\n    }).unsubscribe;\n  }, [control, name, disabled]);\n\n  const updateValues = React.useCallback(\n    <\n      T extends Partial<\n        FieldArrayWithId<TFieldValues, TFieldArrayName, TKeyName>\n      >[],\n    >(\n      updatedFieldArrayValues: T,\n    ) => {\n      _actioned.current = true;\n      control._setFieldArray(name, updatedFieldArrayValues);\n    },\n    [control, name],\n  );\n\n  const append = (\n    value:\n      | Partial<FieldArray<TFieldValues, TFieldArrayName>>\n      | Partial<FieldArray<TFieldValues, TFieldArrayName>>[],\n    options?: FieldArrayMethodProps,\n  ) => {\n    if (disabled) {\n      return;\n    }\n\n    const appendValue = convertToArrayPayload(cloneObject(value));\n    const updatedFieldArrayValues = appendAt(\n      control._getFieldArray(name),\n      appendValue,\n    );\n    control._names.focus = getFocusFieldName(\n      name,\n      updatedFieldArrayValues.length - 1,\n      options,\n    );\n    ids.current = appendAt(ids.current, appendValue.map(generateId));\n    updateValues(updatedFieldArrayValues);\n    setFields(updatedFieldArrayValues);\n    control._setFieldArray(name, updatedFieldArrayValues, appendAt, {\n      argA: fillEmptyArray(value),\n    });\n  };\n\n  const prepend = (\n    value:\n      | Partial<FieldArray<TFieldValues, TFieldArrayName>>\n      | Partial<FieldArray<TFieldValues, TFieldArrayName>>[],\n    options?: FieldArrayMethodProps,\n  ) => {\n    if (disabled) {\n      return;\n    }\n\n    const prependValue = convertToArrayPayload(cloneObject(value));\n    const updatedFieldArrayValues = prependAt(\n      control._getFieldArray(name),\n      prependValue,\n    );\n    control._names.focus = getFocusFieldName(name, 0, options);\n    ids.current = prependAt(ids.current, prependValue.map(generateId));\n    updateValues(updatedFieldArrayValues);\n    setFields(updatedFieldArrayValues);\n    control._setFieldArray(name, updatedFieldArrayValues, prependAt, {\n      argA: fillEmptyArray(value),\n    });\n  };\n\n  const remove = (index?: number | number[]) => {\n    if (disabled) {\n      return;\n    }\n\n    const updatedFieldArrayValues: Partial<\n      FieldArrayWithId<TFieldValues, TFieldArrayName, TKeyName>\n    >[] = removeArrayAt(control._getFieldArray(name), index);\n    ids.current = removeArrayAt(ids.current, index);\n    updateValues(updatedFieldArrayValues);\n    setFields(updatedFieldArrayValues);\n    !Array.isArray(get(control._fields, name)) &&\n      set(control._fields, name, undefined);\n    control._setFieldArray(name, updatedFieldArrayValues, removeArrayAt, {\n      argA: index,\n    });\n  };\n\n  const insert = (\n    index: number,\n    value:\n      | Partial<FieldArray<TFieldValues, TFieldArrayName>>\n      | Partial<FieldArray<TFieldValues, TFieldArrayName>>[],\n    options?: FieldArrayMethodProps,\n  ) => {\n    if (disabled) {\n      return;\n    }\n\n    const insertValue = convertToArrayPayload(cloneObject(value));\n    const updatedFieldArrayValues = insertAt(\n      control._getFieldArray(name),\n      index,\n      insertValue,\n    );\n    control._names.focus = getFocusFieldName(name, index, options);\n    ids.current = insertAt(ids.current, index, insertValue.map(generateId));\n    updateValues(updatedFieldArrayValues);\n    setFields(updatedFieldArrayValues);\n    control._setFieldArray(name, updatedFieldArrayValues, insertAt, {\n      argA: index,\n      argB: fillEmptyArray(value),\n    });\n  };\n\n  const swap = (indexA: number, indexB: number) => {\n    if (disabled) {\n      return;\n    }\n\n    const updatedFieldArrayValues = control._getFieldArray(name);\n    swapArrayAt(updatedFieldArrayValues, indexA, indexB);\n    swapArrayAt(ids.current, indexA, indexB);\n    updateValues(updatedFieldArrayValues);\n    setFields(updatedFieldArrayValues);\n    control._setFieldArray(\n      name,\n      updatedFieldArrayValues,\n      swapArrayAt,\n      {\n        argA: indexA,\n        argB: indexB,\n      },\n      false,\n    );\n  };\n\n  const move = (from: number, to: number) => {\n    if (disabled) {\n      return;\n    }\n\n    const updatedFieldArrayValues = control._getFieldArray(name);\n    moveArrayAt(updatedFieldArrayValues, from, to);\n    moveArrayAt(ids.current, from, to);\n    updateValues(updatedFieldArrayValues);\n    setFields(updatedFieldArrayValues);\n    control._setFieldArray(\n      name,\n      updatedFieldArrayValues,\n      moveArrayAt,\n      {\n        argA: from,\n        argB: to,\n      },\n      false,\n    );\n  };\n\n  const update = (\n    index: number,\n    value: FieldArray<TFieldValues, TFieldArrayName>,\n  ) => {\n    if (disabled) {\n      return;\n    }\n\n    const updateValue = cloneObject(value);\n    const updatedFieldArrayValues = updateAt(\n      control._getFieldArray<\n        FieldArrayWithId<TFieldValues, TFieldArrayName, TKeyName>\n      >(name),\n      index,\n      updateValue as FieldArrayWithId<TFieldValues, TFieldArrayName, TKeyName>,\n    );\n    ids.current = [...updatedFieldArrayValues].map((item, i) =>\n      !item || i === index ? generateId() : ids.current[i],\n    );\n    updateValues(updatedFieldArrayValues);\n    setFields([...updatedFieldArrayValues]);\n    control._setFieldArray(\n      name,\n      updatedFieldArrayValues,\n      updateAt,\n      {\n        argA: index,\n        argB: updateValue,\n      },\n      true,\n      false,\n    );\n  };\n\n  const replace = (\n    value:\n      | Partial<FieldArray<TFieldValues, TFieldArrayName>>\n      | Partial<FieldArray<TFieldValues, TFieldArrayName>>[],\n  ) => {\n    if (disabled) {\n      return;\n    }\n\n    const updatedFieldArrayValues = convertToArrayPayload(cloneObject(value));\n    ids.current = updatedFieldArrayValues.map(generateId);\n    updateValues([...updatedFieldArrayValues]);\n    setFields([...updatedFieldArrayValues]);\n    control._setFieldArray(\n      name,\n      [...updatedFieldArrayValues],\n      <T>(data: T): T => data,\n      {},\n      true,\n      false,\n    );\n  };\n\n  React.useEffect(() => {\n    if (disabled) {\n      control._state.actionArrayLengths.delete(name);\n      return;\n    }\n\n    control._state.action = false;\n    control._state.actionArrayLengths.delete(name);\n\n    isWatched(name, control._names) &&\n      control._subjects.state.next({\n        ...control._formState,\n      } as FormState<TFieldValues>);\n\n    const validationModes = getValidationModes(control._options.mode);\n\n    if (\n      _actioned.current &&\n      (!validationModes.isOnSubmit || control._formState.isSubmitted) &&\n      !getValidationModes(control._options.reValidateMode).isOnSubmit &&\n      !validationModes.isOnBlur\n    ) {\n      if (control._options.resolver) {\n        control._runSchema([name]).then((result) => {\n          control._updateIsValidating([name]);\n          const error = get(result.errors, name);\n          const existingError = get(control._formState.errors, name);\n          const existingErrorType =\n            existingError && (existingError.type || existingError.root?.type);\n          const existingErrorMessage =\n            existingError &&\n            (existingError.message || existingError.root?.message);\n\n          if (\n            existingError\n              ? (!error && existingErrorType) ||\n                (error &&\n                  (existingErrorType !== error.type ||\n                    existingErrorMessage !== error.message))\n              : error && error.type\n          ) {\n            if (error) {\n              isObject(error) &&\n              !Object.keys(error).some((key) => !Number.isNaN(+key))\n                ? updateFieldArrayRootError(\n                    control._formState.errors as FieldErrors<TFieldValues>,\n                    { [name]: error } as Partial<Record<string, FieldError>>,\n                    name,\n                  )\n                : set(control._formState.errors, name, error);\n            } else {\n              unset(control._formState.errors, name);\n            }\n            control._subjects.state.next({\n              errors: control._formState.errors as FieldErrors<TFieldValues>,\n            });\n          }\n        });\n      } else {\n        const field: Field = get(control._fields, name);\n        if (\n          field &&\n          field._f &&\n          !(\n            getValidationModes(control._options.reValidateMode).isOnSubmit &&\n            getValidationModes(control._options.mode).isOnSubmit\n          )\n        ) {\n          validateField(\n            field,\n            control._names.disabled,\n            control._formValues,\n            control._options.criteriaMode === VALIDATION_MODE.all,\n            control._options.shouldUseNativeValidation,\n            true,\n          ).then(\n            (error) =>\n              !isEmptyObject(error) &&\n              control._subjects.state.next({\n                errors: updateFieldArrayRootError(\n                  control._formState.errors as FieldErrors<TFieldValues>,\n                  error,\n                  name,\n                ) as FieldErrors<TFieldValues>,\n              }),\n          );\n        }\n      }\n    }\n\n    // External updates that change `fields` (e.g. reset() or setValue() on\n    // the array) already notify subscribers with the up-to-date values\n    // themselves, so only re-broadcast here for genuine array method calls.\n    _actioned.current &&\n      control._subjects.state.next({\n        name,\n        values: cloneObject(control._formValues) as TFieldValues,\n      });\n\n    control._names.focus &&\n      iterateFieldsByAction(control._fields, (ref, key: string) => {\n        if (\n          control._names.focus &&\n          key.startsWith(control._names.focus) &&\n          ref.focus\n        ) {\n          ref.focus();\n          return 1;\n        }\n        return;\n      });\n\n    control._names.focus = '';\n\n    control._setValid();\n    _actioned.current = false;\n  }, [fields, name, control, disabled]);\n\n  React.useEffect(() => {\n    if (!disabled) {\n      !get(control._formValues, name) && control._setFieldArray(name);\n    }\n\n    return () => {\n      control._state.actionArrayLengths.delete(name);\n\n      if (disabled) {\n        return;\n      }\n\n      const shouldKeepFieldArrayValues = !(\n        control._options.shouldUnregister || shouldUnregister\n      );\n      const updateMounted = (name: InternalFieldName, value: boolean) => {\n        const field: Field = get(control._fields, name);\n        if (field && field._f) {\n          field._f.mount = value;\n        }\n      };\n\n      if (_actioned.current && shouldKeepFieldArrayValues) {\n        control._subjects.state.next({\n          name,\n          values: cloneObject(control._formValues) as TFieldValues,\n        });\n      }\n\n      shouldKeepFieldArrayValues\n        ? updateMounted(name, false)\n        : control.unregister(name as FieldPath<TFieldValues>);\n    };\n  }, [name, control, keyName, shouldUnregister, disabled]);\n\n  return {\n    swap: React.useCallback(swap, [updateValues, name, control, disabled]),\n    move: React.useCallback(move, [updateValues, name, control, disabled]),\n    prepend: React.useCallback(prepend, [\n      updateValues,\n      name,\n      control,\n      disabled,\n    ]),\n    append: React.useCallback(append, [updateValues, name, control, disabled]),\n    remove: React.useCallback(remove, [updateValues, name, control, disabled]),\n    insert: React.useCallback(insert, [updateValues, name, control, disabled]),\n    update: React.useCallback(update, [updateValues, name, control, disabled]),\n    replace: React.useCallback(replace, [\n      updateValues,\n      name,\n      control,\n      disabled,\n    ]),\n    fields: React.useMemo(\n      () =>\n        fields.map((field, index) => ({\n          ...field,\n          ...(isBoolean(disabled) ? { disabled } : {}),\n          [keyName]: ids.current[index] || generateId(),\n        })) as FieldArrayWithId<TFieldValues, TFieldArrayName, TKeyName>[],\n      [fields, keyName, disabled],\n    ),\n  };\n}\n","import type {\n  FieldArray as FieldArrayType,\n  FieldArrayPath,\n  FieldArrayProps,\n  FieldValues,\n} from './types';\nimport { useFieldArray } from './useFieldArray';\n\ntype FieldArray<\n  TFieldValues extends FieldValues = FieldValues,\n  TFieldArrayName extends FieldArrayPath<TFieldValues> =\n    FieldArrayPath<TFieldValues>,\n> = FieldArrayType<TFieldValues, TFieldArrayName>;\n\n/**\n * Component based on `useFieldArray` hook to work with controlled component.\n *\n * @example\n * ```tsx\n * function App() {\n *   const { control, register } = useForm<FormValues>({\n *     defaultValues: {\n *       test: [\n *         {\n *           value: '',\n *         },\n *       ],\n *     },\n *   });\n *\n *   return (\n *     <form>\n *       <FieldArray\n *         control={control}\n *         name=\"test\"\n *         render={({ fields }) =>\n *           fields.map((field, index) => (\n *             <input key={field.id} {...register(`test.${index}.value`)} />\n *           ))\n *         }\n *       />\n *     </form>\n *   );\n * }\n * ```\n */\nconst FieldArray = <\n  TFieldValues extends FieldValues = FieldValues,\n  TName extends FieldArrayPath<TFieldValues> = FieldArrayPath<TFieldValues>,\n  TKeyName extends string = 'id',\n>(\n  props: FieldArrayProps<TFieldValues, TName, TKeyName>,\n) => props.render(useFieldArray<TFieldValues, TName, TKeyName>(props));\n\nexport { FieldArray };\n","import type { FieldValues } from '../types';\n\nimport isDateObject from './isDateObject';\nimport { isObjectType } from './isObject';\n\nexport const flatten = (obj: FieldValues) => {\n  const output: FieldValues = {};\n\n  for (const key of Object.keys(obj)) {\n    if (\n      isObjectType(obj[key]) &&\n      obj[key] !== null &&\n      !isDateObject(obj[key])\n    ) {\n      const nested = flatten(obj[key]);\n\n      for (const nestedKey of Object.keys(nested)) {\n        output[`${key}.${nestedKey}`] = nested[nestedKey];\n      }\n    } else {\n      output[key] = obj[key];\n    }\n  }\n\n  return output;\n};\n","export default function noop() {}\n","import React from 'react';\n\nimport type {\n  Control,\n  FieldValues,\n  FormProviderProps,\n  UseFormReturn,\n} from './types';\nimport { HookFormControlContext } from './useFormControlContext';\n\nconst HookFormContext = React.createContext<UseFormReturn | null>(null);\nHookFormContext.displayName = 'HookFormContext';\n\n/**\n * This custom hook allows you to access the form context. useFormContext is intended to be used in deeply nested structures, where it would become inconvenient to pass the context as a prop. To be used with {@link FormProvider}.\n *\n * @remarks\n * [API](https://react-hook-form.com/docs/useformcontext) • [Demo](https://codesandbox.io/s/react-hook-form-v7-form-context-ytudi)\n *\n * @returns return all useForm methods\n *\n * @example\n * ```tsx\n * function App() {\n *   const methods = useForm();\n *   const onSubmit = data => console.log(data);\n *\n *   return (\n *     <FormProvider {...methods} >\n *       <form onSubmit={methods.handleSubmit(onSubmit)}>\n *         <NestedInput />\n *         <input type=\"submit\" />\n *       </form>\n *     </FormProvider>\n *   );\n * }\n *\n *  function NestedInput() {\n *   const { register } = useFormContext(); // retrieve all hook methods\n *   return <input {...register(\"test\")} />;\n * }\n * ```\n */\nexport const useFormContext = <\n  TFieldValues extends FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>(): UseFormReturn<TFieldValues, TContext, TTransformedValues> =>\n  React.useContext(HookFormContext) as UseFormReturn<\n    TFieldValues,\n    TContext,\n    TTransformedValues\n  >;\n\n/**\n * A provider component that propagates the `useForm` methods to all children components via [React Context](https://react.dev/reference/react/useContext) API. To be used with {@link useFormContext}.\n *\n * @remarks\n * [API](https://react-hook-form.com/docs/useformcontext) • [Demo](https://codesandbox.io/s/react-hook-form-v7-form-context-ytudi)\n *\n * @param props - all useForm methods\n *\n * @example\n * ```tsx\n * function App() {\n *   const methods = useForm();\n *   const onSubmit = data => console.log(data);\n *\n *   return (\n *     <FormProvider {...methods} >\n *       <form onSubmit={methods.handleSubmit(onSubmit)}>\n *         <NestedInput />\n *         <input type=\"submit\" />\n *       </form>\n *     </FormProvider>\n *   );\n * }\n *\n *  function NestedInput() {\n *   const { register } = useFormContext(); // retrieve all hook methods\n *   return <input {...register(\"test\")} />;\n * }\n * ```\n */\nexport const FormProvider = <\n  TFieldValues extends FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>({\n  children,\n  watch,\n  getValues,\n  getFieldState,\n  setError,\n  clearErrors,\n  setValue,\n  setValues,\n  trigger,\n  formState,\n  resetField,\n  reset,\n  resetDefaultValues,\n  handleSubmit,\n  unregister,\n  control,\n  register,\n  setFocus,\n  subscribe,\n}: FormProviderProps<TFieldValues, TContext, TTransformedValues>) => {\n  const memoizedValue = React.useMemo<\n    UseFormReturn<TFieldValues, TContext, TTransformedValues>\n  >(\n    () => ({\n      watch,\n      getValues,\n      getFieldState,\n      setError,\n      clearErrors,\n      setValue,\n      setValues,\n      trigger,\n      formState,\n      resetField,\n      reset,\n      resetDefaultValues,\n      handleSubmit,\n      unregister,\n      control,\n      register,\n      setFocus,\n      subscribe,\n    }),\n    [\n      clearErrors,\n      control,\n      formState,\n      getFieldState,\n      getValues,\n      handleSubmit,\n      register,\n      reset,\n      resetDefaultValues,\n      resetField,\n      setError,\n      setFocus,\n      setValue,\n      setValues,\n      subscribe,\n      trigger,\n      unregister,\n      watch,\n    ],\n  );\n\n  return (\n    <HookFormContext.Provider value={memoizedValue as unknown as UseFormReturn}>\n      <HookFormControlContext.Provider value={memoizedValue.control as Control}>\n        {children}\n      </HookFormControlContext.Provider>\n    </HookFormContext.Provider>\n  );\n};\n","import React from 'react';\n\nimport { jsonToFormData } from './utils/formData';\nimport isFunction from './utils/isFunction';\nimport isString from './utils/isString';\nimport { safeJSONStringify } from './utils/json';\nimport noop from './utils/noop';\nimport type { FieldValues, FormProps } from './types';\nimport { useFormContext } from './useFormContext';\n\nconst POST_REQUEST = 'post';\n\nfunction defaultValidateStatus(status: number) {\n  return status >= 200 && status < 300;\n}\n\n/**\n * Form component to manage submission.\n *\n * @param props - to setup submission detail. {@link FormProps}\n *\n * @returns form component or headless render prop.\n *\n * @example\n * ```tsx\n * function App() {\n *   const { control, formState: { errors } } = useForm();\n *\n *   return (\n *     <Form action=\"/api\" control={control}>\n *       <input {...register(\"name\")} />\n *       <p>{errors?.root?.server && 'Server error'}</p>\n *       <button>Submit</button>\n *     </Form>\n *   );\n * }\n * ```\n */\nfunction Form<\n  TFieldValues extends FieldValues,\n  TTransformedValues = TFieldValues,\n>(props: FormProps<TFieldValues, TTransformedValues>): React.ReactNode {\n  const methods = useFormContext<TFieldValues, any, TTransformedValues>();\n  const [mounted, setMounted] = React.useState(false);\n  const {\n    control = methods.control,\n    onSubmit = noop,\n    children,\n    action,\n    method = POST_REQUEST,\n    headers,\n    encType,\n    onError = noop,\n    render,\n    onSuccess = noop,\n    validateStatus = defaultValidateStatus,\n    ...rest\n  } = props;\n\n  const handleSubmit = React.useMemo(() => {\n    return control.handleSubmit(async (data, event) => {\n      const formData = jsonToFormData(data);\n      const formDataJson = safeJSONStringify(data);\n\n      if (onSubmit) {\n        await onSubmit({\n          data,\n          event,\n          method,\n          formData,\n          formDataJson,\n        });\n      }\n\n      if (isString(action)) {\n        try {\n          const shouldStringifySubmissionData =\n            (headers &&\n              headers['Content-Type'] &&\n              headers['Content-Type'].includes('json')) ||\n            (encType && encType.includes('json'));\n\n          const response = await fetch(action, {\n            method,\n            headers: {\n              ...headers,\n              ...(encType &&\n                encType !== 'multipart/form-data' && {\n                  'Content-Type': encType,\n                }),\n            },\n            body: shouldStringifySubmissionData ? formDataJson : formData,\n          });\n\n          if (response && !validateStatus(response.status)) {\n            onError({ response });\n            return { type: String(response.status) };\n          } else {\n            onSuccess({ response });\n          }\n        } catch (error: unknown) {\n          onError({ error });\n          return { type: '' };\n        }\n      }\n\n      if (isFunction(action)) {\n        try {\n          await action(formData);\n        } catch (error: unknown) {\n          onError({ error });\n          return { type: '' };\n        }\n      }\n\n      // Return nothing when successful.\n      return;\n    });\n  }, [\n    control,\n    onSubmit,\n    method,\n    action,\n    headers,\n    encType,\n    validateStatus,\n    onError,\n    onSuccess,\n  ]);\n\n  const submit = React.useCallback(\n    async (event?: React.BaseSyntheticEvent) => {\n      const err = await handleSubmit(event);\n\n      if (err && control) {\n        control._subjects.state.next({ isSubmitSuccessful: false });\n        control.setError('root.server', err);\n      }\n    },\n    [handleSubmit, control],\n  );\n\n  React.useEffect(() => {\n    setMounted(true);\n  }, []);\n\n  if (render) {\n    return render({ submit });\n  }\n\n  // React forbids passing `method`/`encType` alongside a function `action`\n  // (a Server-Action-style submission) -- it manages those itself and warns\n  // if they're present, so they're only rendered for string/URL actions.\n  return (\n    <form\n      noValidate={mounted}\n      action={action}\n      {...(!isFunction(action) && { method, encType })}\n      onSubmit={submit}\n      {...rest}\n    >\n      {children}\n    </form>\n  );\n}\n\nexport { Form };\n","import type { ReactNode } from 'react';\n\nimport type {\n  FieldValues,\n  FormState as FormStateType,\n  UseFormStateProps,\n  UseFormStateReturn,\n} from './types';\nimport { useFormState } from './useFormState';\n\nexport type FormStateProps<\n  TFieldValues extends FieldValues,\n  TTransformedValues = TFieldValues,\n> = UseFormStateProps<TFieldValues, TTransformedValues> & {\n  render: (values: UseFormStateReturn<TFieldValues>) => ReactNode;\n};\n\nexport type FormState<TFieldValues extends FieldValues> =\n  FormStateType<TFieldValues>;\n\nexport const FormState = <\n  TFieldValues extends FieldValues,\n  TTransformedValues = TFieldValues,\n>({\n  control,\n  disabled,\n  exact,\n  name,\n  render,\n}: FormStateProps<TFieldValues, TTransformedValues>) =>\n  render(useFormState({ control, name, disabled, exact }));\n\n/** @deprecated Use `FormState` instead. Kept as an alias for backward compatibility. */\nexport const FormStateSubscribe = FormState;\n\n/** @deprecated Use `FormStateProps` instead. Kept as an alias for backward compatibility. */\nexport type FormStateSubscribeProps<\n  TFieldValues extends FieldValues,\n  TTransformedValues = TFieldValues,\n> = FormStateProps<TFieldValues, TTransformedValues>;\n","import type { Noop } from '../types';\n\nexport type Observer<T> = {\n  next: (value: T) => void;\n};\n\nexport type Subscription = {\n  unsubscribe: Noop;\n};\n\nexport type Subject<T> = {\n  readonly observers: Observer<T>[];\n  subscribe: (value: Observer<T>) => Subscription;\n  unsubscribe: Noop;\n} & Observer<T>;\n\nexport default <T>(): Subject<T> => {\n  let _observers: Observer<T>[] = [];\n\n  const next = (value: T) => {\n    for (const observer of _observers) {\n      observer.next && observer.next(value);\n    }\n  };\n\n  const subscribe = (observer: Observer<T>): Subscription => {\n    _observers.push(observer);\n    return {\n      unsubscribe: () => {\n        _observers = _observers.filter((o) => o !== observer);\n      },\n    };\n  };\n\n  const unsubscribe = () => {\n    _observers = [];\n  };\n\n  return {\n    get observers() {\n      return _observers;\n    },\n    next,\n    subscribe,\n    unsubscribe,\n  };\n};\n","import isObject from './isObject';\n\nexport default function extractFormValues<\n  T extends object,\n  K extends Record<string, unknown>,\n>(fieldsState: T, formValues: K) {\n  const values: Record<string, unknown> = {};\n\n  for (const key in fieldsState) {\n    if (fieldsState.hasOwnProperty(key)) {\n      const fieldState = fieldsState[key];\n      const fieldValue = formValues[key];\n\n      if (fieldState && isObject(fieldState) && fieldValue) {\n        const nestedFieldsState = extractFormValues(\n          fieldState,\n          fieldValue as K,\n        );\n\n        if (isObject(nestedFieldsState)) {\n          values[key] = nestedFieldsState;\n        }\n      } else if (fieldsState[key]) {\n        values[key] = fieldValue;\n      }\n    }\n  }\n\n  return values;\n}\n","import type { FieldElement } from '../types';\n\nexport default (element: FieldElement): element is HTMLSelectElement =>\n  element.type === `select-multiple`;\n","import type { Ref } from '../types';\n\nimport isHTMLElement from './isHTMLElement';\n\nexport default (ref: Ref) => isHTMLElement(ref) && ref.isConnected;\n","import type { FieldValues } from '../types';\nimport get from '../utils/get';\nimport isObject from '../utils/isObject';\n\nfunction isDirtyContainer(value: unknown): boolean {\n  return Array.isArray(value) || isObject(value);\n}\n\nexport default function collectDirtyFieldNames(\n  dirtyTree: FieldValues,\n  cachedDirtyFields: FieldValues,\n  prefix = '',\n  names: string[] = [],\n) {\n  for (const key in dirtyTree) {\n    const path = prefix ? `${prefix}.${key}` : key;\n    const value = dirtyTree[key];\n\n    if (\n      isDirtyContainer(value) &&\n      isDirtyContainer(get(cachedDirtyFields, path))\n    ) {\n      collectDirtyFieldNames(value, cachedDirtyFields, path, names);\n    } else {\n      names.push(path);\n    }\n  }\n\n  return names;\n}\n","import type { FieldRefs } from '../types';\nimport deepEqual from '../utils/deepEqual';\nimport isNullOrUndefined from '../utils/isNullOrUndefined';\nimport isObject from '../utils/isObject';\nimport isPrimitive from '../utils/isPrimitive';\nimport isUndefined from '../utils/isUndefined';\nimport objectHasFunction from '../utils/objectHasFunction';\n\nfunction isTraversable<T>(value: T): boolean {\n  return Array.isArray(value) || (isObject(value) && !objectHasFunction(value));\n}\n\nfunction isRegisteredLeaf(fieldRef: unknown): boolean {\n  return !!(fieldRef && '_f' in (fieldRef as object));\n}\n\nfunction isEmptyDirtyContainer(value: Record<string, any>): boolean {\n  return Array.isArray(value)\n    ? !value.some((item) => !isUndefined(item))\n    : !Object.keys(value).length;\n}\n\nfunction clearDirtyField(container: Record<string, any>, key: string) {\n  if (Array.isArray(container)) {\n    (container as any)[key] = undefined;\n  } else {\n    delete container[key];\n  }\n}\n\nfunction markFieldsDirty<T>(\n  data: T,\n  fields: Record<string, any> = {},\n  fieldRefs?: Record<string, any>,\n) {\n  for (const key in data) {\n    const value = data[key];\n    const fieldRef = fieldRefs && fieldRefs[key];\n\n    if (\n      isTraversable(value) &&\n      (!Array.isArray(value) || !isRegisteredLeaf(fieldRef))\n    ) {\n      fields[key] = Array.isArray(value) ? [] : {};\n      markFieldsDirty(value, fields[key], fieldRef);\n\n      if (isEmptyDirtyContainer(fields[key])) {\n        clearDirtyField(fields, key);\n      }\n    } else if (!isUndefined(value)) {\n      fields[key] = true;\n    }\n  }\n\n  return fields;\n}\n\nexport default function getDirtyFields<T>(\n  data: T,\n  formValues: T,\n  dirtyFieldsFromValues?: Record<\n    Extract<keyof T, string>,\n    ReturnType<typeof markFieldsDirty> | boolean\n  >,\n  fieldRefs?: FieldRefs,\n) {\n  if (!dirtyFieldsFromValues) {\n    dirtyFieldsFromValues = markFieldsDirty(formValues, {}, fieldRefs);\n  }\n\n  for (const key in data) {\n    const value = data[key];\n    const fieldRef = fieldRefs && (fieldRefs as Record<string, any>)[key];\n\n    if (\n      isTraversable(value) &&\n      (!Array.isArray(value) || !isRegisteredLeaf(fieldRef))\n    ) {\n      if (isUndefined(formValues) || isPrimitive(dirtyFieldsFromValues[key])) {\n        dirtyFieldsFromValues[key] = markFieldsDirty(\n          value,\n          Array.isArray(value) ? [] : {},\n          fieldRef,\n        );\n      } else {\n        getDirtyFields(\n          value,\n          isNullOrUndefined(formValues) ? {} : formValues[key],\n          dirtyFieldsFromValues[key],\n          fieldRef,\n        );\n      }\n\n      if (isEmptyDirtyContainer(dirtyFieldsFromValues[key])) {\n        clearDirtyField(dirtyFieldsFromValues, key);\n      }\n    } else if (deepEqual(value, formValues[key])) {\n      clearDirtyField(dirtyFieldsFromValues, key);\n    } else {\n      dirtyFieldsFromValues[key] = true;\n    }\n  }\n\n  return dirtyFieldsFromValues;\n}\n","import isFunction from './isFunction';\n\nexport default <T>(data: T): boolean => {\n  for (const key in data) {\n    if (isFunction(data[key])) {\n      return true;\n    }\n  }\n  return false;\n};\n","import type { Field, NativeFieldValue } from '../types';\nimport isString from '../utils/isString';\nimport isUndefined from '../utils/isUndefined';\n\nexport default <T extends NativeFieldValue>(\n  value: T,\n  { valueAsNumber, valueAsDate, setValueAs }: Field['_f'],\n) =>\n  isUndefined(value)\n    ? value\n    : valueAsNumber\n      ? value === ''\n        ? NaN\n        : value\n          ? +value\n          : value\n      : valueAsDate && isString(value)\n        ? new Date(value)\n        : setValueAs\n          ? setValueAs(value)\n          : value;\n","import type { Field } from '../types';\nimport isCheckBox from '../utils/isCheckBoxInput';\nimport isFileInput from '../utils/isFileInput';\nimport isMultipleSelect from '../utils/isMultipleSelect';\nimport isRadioInput from '../utils/isRadioInput';\n\nimport getCheckboxValue from './getCheckboxValue';\nimport getFieldValueAs from './getFieldValueAs';\nimport getRadioValue from './getRadioValue';\n\nexport default function getFieldValue(_f: Field['_f']) {\n  const ref = _f.ref;\n\n  if (isFileInput(ref)) {\n    return ref.files;\n  }\n\n  if (isRadioInput(ref)) {\n    return getRadioValue(_f.refs).value;\n  }\n\n  if (isMultipleSelect(ref)) {\n    return [...ref.selectedOptions].map(({ value }) => value);\n  }\n\n  if (isCheckBox(ref)) {\n    return getCheckboxValue(_f.refs).value;\n  }\n\n  return getFieldValueAs(ref.value, _f);\n}\n","import type {\n  CriteriaMode,\n  Field,\n  FieldName,\n  FieldRefs,\n  FieldValues,\n  InternalFieldName,\n} from '../types';\nimport { get } from '../utils';\nimport set from '../utils/set';\n\nexport default <TFieldValues extends FieldValues>(\n  fieldsNames: Set<InternalFieldName> | InternalFieldName[],\n  _fields: FieldRefs,\n  criteriaMode?: CriteriaMode,\n  shouldUseNativeValidation?: boolean | undefined,\n) => {\n  const fields: Record<InternalFieldName, Field['_f']> = {};\n\n  for (const name of fieldsNames) {\n    const field: Field = get(_fields, name);\n\n    field && set(fields, name, field._f);\n  }\n\n  return {\n    criteriaMode,\n    names: [...fieldsNames] as FieldName<TFieldValues>[],\n    fields,\n    shouldUseNativeValidation,\n  };\n};\n","import type {\n  ValidationRule,\n  ValidationValue,\n  ValidationValueMessage,\n} from '../types';\nimport isObject from '../utils/isObject';\nimport isRegex from '../utils/isRegex';\nimport isUndefined from '../utils/isUndefined';\n\nexport default <T extends ValidationValue>(\n  rule?: ValidationRule<T> | ValidationValueMessage<T>,\n) =>\n  isUndefined(rule)\n    ? rule\n    : isRegex(rule)\n      ? rule.source\n      : isObject(rule)\n        ? isRegex(rule.value)\n          ? rule.value.source\n          : rule.value\n        : rule;\n","import type { Field, Validate } from '../types';\nimport isFunction from '../utils/isFunction';\nimport isObject from '../utils/isObject';\n\nconst ASYNC_FUNCTION = 'AsyncFunction';\n\nexport default (fieldReference: Field['_f']) => {\n  if (!fieldReference || !fieldReference.validate) return false;\n\n  if (isFunction(fieldReference.validate)) {\n    return fieldReference.validate.constructor.name === ASYNC_FUNCTION;\n  }\n\n  if (isObject(fieldReference.validate)) {\n    for (const key in fieldReference.validate) {\n      if (\n        (fieldReference.validate[key] as Validate<unknown, unknown>).constructor\n          .name === ASYNC_FUNCTION\n      ) {\n        return true;\n      }\n    }\n  }\n\n  return false;\n};\n","import type { FieldError, FieldErrors, FieldValues } from '../types';\nimport get from '../utils/get';\nimport isKey from '../utils/isKey';\n\nexport default function schemaErrorLookup<T extends FieldValues = FieldValues>(\n  errors: FieldErrors<T>,\n  _fields: FieldValues,\n  name: string,\n): {\n  error?: FieldError;\n  name: string;\n} {\n  const error = get(errors, name);\n\n  if (error || isKey(name)) {\n    return {\n      error,\n      name,\n    };\n  }\n\n  const names = name.split('.');\n\n  while (names.length) {\n    const fieldName = names.join('.');\n    const field = get(_fields, fieldName);\n    const foundError = get(errors, fieldName);\n\n    if (field && !Array.isArray(field) && name !== fieldName) {\n      return { name };\n    }\n\n    if (foundError && foundError.type) {\n      return {\n        name: fieldName,\n        error: foundError,\n      };\n    }\n\n    if (foundError && foundError.root && foundError.root.type) {\n      return {\n        name: `${fieldName}.root`,\n        error: foundError.root,\n      };\n    }\n\n    names.pop();\n  }\n\n  return {\n    name,\n  };\n}\n","import {\n  EVENTS,\n  INPUT_VALIDATION_RULES,\n  ROOT_ERROR_TYPE,\n  VALIDATION_MODE,\n} from '../constants';\nimport type {\n  BatchFieldArrayUpdate,\n  ChangeHandler,\n  Control,\n  DeepPartial,\n  DelayCallback,\n  EventType,\n  Field,\n  FieldError,\n  FieldErrors,\n  FieldNamesMarkedBoolean,\n  FieldPath,\n  FieldPathValue,\n  FieldRefs,\n  FieldValues,\n  FormState,\n  FromSubscribe,\n  GetIsDirty,\n  GetValuesConfig,\n  InternalFieldName,\n  Names,\n  Path,\n  ReadFormState,\n  Ref,\n  SetFieldValue,\n  SetValueConfig,\n  Subjects,\n  TriggerConfig,\n  UseFormClearErrors,\n  UseFormGetFieldState,\n  UseFormGetValues,\n  UseFormHandleSubmit,\n  UseFormProps,\n  UseFormRegister,\n  UseFormReset,\n  UseFormResetDefaultValues,\n  UseFormResetField,\n  UseFormReturn,\n  UseFormSetError,\n  UseFormSetFocus,\n  UseFormSetValue,\n  UseFormSetValues,\n  UseFormSubscribe,\n  UseFormTrigger,\n  UseFormUnregister,\n  UseFormWatch,\n  ValidateFormEventType,\n  WatchInternal,\n  WatchObserver,\n} from '../types';\nimport cloneObject from '../utils/cloneObject';\nimport compact from '../utils/compact';\nimport convertToArrayPayload from '../utils/convertToArrayPayload';\nimport createSubject from '../utils/createSubject';\nimport deepEqual from '../utils/deepEqual';\nimport extractFormValues from '../utils/extractFormValues';\nimport { flatten } from '../utils/flatten';\nimport get from '../utils/get';\nimport isBoolean from '../utils/isBoolean';\nimport isCheckBoxInput from '../utils/isCheckBoxInput';\nimport isDateObject from '../utils/isDateObject';\nimport isEmptyObject from '../utils/isEmptyObject';\nimport isFileInput from '../utils/isFileInput';\nimport isFunction from '../utils/isFunction';\nimport isHTMLElement from '../utils/isHTMLElement';\nimport isKey from '../utils/isKey';\nimport isMultipleSelect from '../utils/isMultipleSelect';\nimport isNullOrUndefined from '../utils/isNullOrUndefined';\nimport isObject from '../utils/isObject';\nimport isRadioOrCheckbox from '../utils/isRadioOrCheckbox';\nimport isString from '../utils/isString';\nimport isUndefined from '../utils/isUndefined';\nimport isWeb from '../utils/isWeb';\nimport live from '../utils/live';\nimport set from '../utils/set';\nimport stringToPath from '../utils/stringToPath';\nimport unset from '../utils/unset';\n\nimport collectDirtyFieldNames from './collectDirtyFieldNames';\nimport generateWatchOutput from './generateWatchOutput';\nimport getDirtyFields from './getDirtyFields';\nimport getEventValue from './getEventValue';\nimport getFieldValue from './getFieldValue';\nimport getFieldValueAs from './getFieldValueAs';\nimport getResolverOptions from './getResolverOptions';\nimport getRuleValue from './getRuleValue';\nimport getValidationModes from './getValidationModes';\nimport hasPromiseValidation from './hasPromiseValidation';\nimport hasValidation from './hasValidation';\nimport isNameInFieldArray from './isNameInFieldArray';\nimport isWatched from './isWatched';\nimport iterateFieldsByAction from './iterateFieldsByAction';\nimport schemaErrorLookup from './schemaErrorLookup';\nimport shouldRenderFormState from './shouldRenderFormState';\nimport shouldSubscribeByName from './shouldSubscribeByName';\nimport skipValidation from './skipValidation';\nimport unsetEmptyArray from './unsetEmptyArray';\nimport updateFieldArrayRootError from './updateFieldArrayRootError';\nimport validateField from './validateField';\n\nconst defaultOptions = {\n  mode: VALIDATION_MODE.onSubmit,\n  reValidateMode: VALIDATION_MODE.onChange,\n  shouldFocusError: true,\n} as const;\n\nconst FORM_ERROR_TYPE = 'form';\n\nconst updateDirtyFields = (\n  dirtyFields: Record<string, unknown>,\n  nextDirtyFields: Record<string, unknown>,\n) => {\n  for (const key in dirtyFields) {\n    if (!(key in nextDirtyFields)) {\n      delete dirtyFields[key];\n    }\n  }\n\n  Object.assign(dirtyFields, nextDirtyFields);\n};\n\nexport const DEFAULT_FORM_STATE = {\n  submitCount: 0,\n  isDirty: false,\n  isReady: false,\n  isValidating: false,\n  isSubmitted: false,\n  isSubmitting: false,\n  isSubmitSuccessful: false,\n  isValid: false,\n  touchedFields: {},\n  dirtyFields: {},\n  validatingFields: {},\n};\n\nexport function createFormControl<\n  TFieldValues extends FieldValues = FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>(\n  props: UseFormProps<TFieldValues, TContext, TTransformedValues> = {},\n): Omit<\n  UseFormReturn<TFieldValues, TContext, TTransformedValues>,\n  'formState'\n> & {\n  formControl: Omit<\n    UseFormReturn<TFieldValues, TContext, TTransformedValues>,\n    'formState'\n  >;\n} {\n  let _options = {\n    ...defaultOptions,\n    ...props,\n  };\n  let _formState: FormState<TFieldValues> & {\n    values?: TFieldValues;\n    name?: string;\n    type?: EventType;\n  } = {\n    ...cloneObject(DEFAULT_FORM_STATE),\n    isLoading: isFunction(_options.defaultValues),\n    errors: _options.errors || {},\n    disabled: _options.disabled || false,\n  };\n  let _fields: FieldRefs = {};\n  let _defaultValues =\n    isObject(_options.defaultValues) || isObject(_options.values)\n      ? cloneObject(_options.defaultValues || _options.values) || {}\n      : {};\n  let _formValues = _options.shouldUnregister\n    ? ({} as TFieldValues)\n    : (cloneObject(_defaultValues) as TFieldValues);\n  let _state = {\n    action: false,\n    actionArrayLengths: new Map<InternalFieldName, number>(),\n    mount: false,\n    watch: false,\n    keepIsValid: false,\n  };\n  let _names: Names = {\n    mount: new Set(),\n    disabled: new Set(),\n    unMount: new Set(),\n    array: new Set(),\n    watch: new Set(),\n    registerName: new Set(),\n  };\n  const delayErrorCallbacks: Partial<Record<InternalFieldName, DelayCallback>> =\n    {};\n  const timers: Partial<Record<InternalFieldName, number>> = {};\n  let _valuesSubscriberCount = 0;\n  let _validationModeBeforeSubmit = getValidationModes(_options.mode);\n  let _validationModeAfterSubmit = getValidationModes(_options.reValidateMode);\n  const defaultProxyFormState: ReadFormState = {\n    isDirty: false,\n    dirtyFields: false,\n    validatingFields: false,\n    touchedFields: false,\n    isValidating: false,\n    isValid: false,\n    errors: false,\n  };\n  const _proxyFormState: ReadFormState = {\n    ...defaultProxyFormState,\n  };\n  let _proxySubscribeFormState = {\n    ..._proxyFormState,\n  };\n  const _subjects: Subjects<TFieldValues> = {\n    array: createSubject(),\n    state: createSubject(),\n  };\n\n  let _setValidCallId = 0;\n\n  const shouldDisplayAllAssociatedErrors =\n    _options.criteriaMode === VALIDATION_MODE.all;\n\n  const debounce =\n    <T extends Function>(name: InternalFieldName, callback: T) =>\n    (wait: number) => {\n      clearTimeout(timers[name]);\n      timers[name] = setTimeout(callback, wait);\n    };\n\n  const _setValid = async (shouldUpdateValid?: boolean) => {\n    if (_state.keepIsValid) {\n      return;\n    }\n    if (\n      !_options.disabled &&\n      (_proxyFormState.isValid ||\n        _proxySubscribeFormState.isValid ||\n        shouldUpdateValid)\n    ) {\n      const callId = ++_setValidCallId;\n      let isValid: boolean;\n      if (_options.resolver) {\n        isValid = isEmptyObject((await _runSchema()).errors);\n        callId === _setValidCallId && _updateIsValidating();\n      } else {\n        isValid = await executeBuiltInValidation({\n          fields: _fields,\n          onlyCheckValid: true,\n          eventType: EVENTS.VALID,\n        });\n      }\n      if (callId === _setValidCallId && isValid !== _formState.isValid) {\n        _subjects.state.next({\n          isValid,\n        });\n      }\n    }\n  };\n\n  const _updateIsValidating = (names?: string[], isValidating?: boolean) => {\n    if (\n      !_options.disabled &&\n      (_proxyFormState.isValidating ||\n        _proxyFormState.validatingFields ||\n        _proxySubscribeFormState.isValidating ||\n        _proxySubscribeFormState.validatingFields)\n    ) {\n      (names || Array.from(_names.mount)).forEach((name) => {\n        if (name) {\n          isValidating\n            ? set(_formState.validatingFields, name, isValidating)\n            : unset(_formState.validatingFields, name);\n        }\n      });\n\n      _subjects.state.next({\n        validatingFields: _formState.validatingFields,\n        isValidating: !isEmptyObject(_formState.validatingFields),\n      });\n    }\n  };\n\n  const _updateDirtyFields = () => {\n    _formState.dirtyFields = getDirtyFields(\n      _defaultValues,\n      _formValues,\n      undefined,\n      _fields,\n    );\n  };\n\n  const _setFieldArray: BatchFieldArrayUpdate = (\n    name,\n    values = [],\n    method,\n    args,\n    shouldSetValues = true,\n    shouldUpdateFieldsAndState = true,\n  ) => {\n    if (args && method && !_options.disabled) {\n      _state.action = true;\n      if (!_state.actionArrayLengths.has(name)) {\n        const preActionFields = get(_fields, name);\n        _state.actionArrayLengths.set(\n          name,\n          Array.isArray(preActionFields) ? preActionFields.length : 0,\n        );\n      }\n      if (shouldUpdateFieldsAndState && Array.isArray(get(_fields, name))) {\n        const fieldValues = method(get(_fields, name), args.argA, args.argB);\n        shouldSetValues && set(_fields, name, fieldValues);\n      }\n\n      if (\n        shouldUpdateFieldsAndState &&\n        Array.isArray(get(_formState.errors, name))\n      ) {\n        const fieldArrayErrors: FieldError[] & { root?: FieldError } = get(\n          _formState.errors,\n          name,\n        );\n        const rootError = fieldArrayErrors.root;\n        const errors =\n          method(fieldArrayErrors, args.argA, args.argB) || fieldArrayErrors;\n\n        if (rootError) {\n          errors.root = rootError;\n        }\n\n        shouldSetValues && set(_formState.errors, name, errors);\n        unsetEmptyArray(_formState.errors, name);\n      }\n\n      if (\n        (_proxyFormState.touchedFields ||\n          _proxySubscribeFormState.touchedFields) &&\n        shouldUpdateFieldsAndState &&\n        Array.isArray(get(_formState.touchedFields, name))\n      ) {\n        const touchedFields = method(\n          get(_formState.touchedFields, name),\n          args.argA,\n          args.argB,\n        );\n        shouldSetValues && set(_formState.touchedFields, name, touchedF