tFieldState,\n  };\n\n  return {\n    ...methods,\n    formControl: methods,\n  };\n}\n","import type { Field } from '../types';\n\nexport default (options: Field['_f']) =>\n  options.mount &&\n  (options.required ||\n    options.min ||\n    options.max ||\n    options.maxLength ||\n    options.minLength ||\n    options.pattern ||\n    options.validate);\n","import type { ValidationModeFlags } from '../types';\n\nexport default (\n  isBlurEvent: boolean,\n  isTouched: boolean,\n  isSubmitted: boolean,\n  reValidateMode: Pick<ValidationModeFlags, 'isOnBlur' | 'isOnChange'>,\n  mode: Partial<ValidationModeFlags>,\n) => {\n  if (mode.isOnAll) {\n    return false;\n  } else if (!isSubmitted && mode.isOnTouch) {\n    return !(isTouched || isBlurEvent);\n  } else if (isSubmitted ? reValidateMode.isOnBlur : mode.isOnBlur) {\n    return !isBlurEvent;\n  } else if (isSubmitted ? reValidateMode.isOnChange : mode.isOnChange) {\n    return isBlurEvent;\n  }\n  return true;\n};\n","import convertToArrayPayload from '../utils/convertToArrayPayload';\n\nexport default <T extends string | readonly string[] | undefined>(\n  name?: T,\n  signalName?: string,\n  exact?: boolean,\n) =>\n  !name ||\n  !signalName ||\n  name === signalName ||\n  convertToArrayPayload(name).some(\n    (currentName) =>\n      currentName &&\n      (exact\n        ? currentName === signalName || currentName.startsWith(signalName + '.')\n        : currentName.startsWith(signalName) ||\n          signalName.startsWith(currentName)),\n  );\n","import { VALIDATION_MODE } from '../constants';\nimport type {\n  FieldValues,\n  FormState,\n  InternalFieldName,\n  ReadFormState,\n} from '../types';\n\nexport default <T extends FieldValues, K extends ReadFormState>(\n  formStateData: Partial<FormState<T>> & {\n    name?: InternalFieldName;\n    values?: T;\n  },\n  _proxyFormState: K,\n  updateFormState: (formState: Partial<FormState<T>>) => void,\n  isRoot?: boolean,\n) => {\n  updateFormState(formStateData);\n  const keys = Object.keys(formStateData).filter((key) => key !== 'name');\n\n  return (\n    !keys.length ||\n    (isRoot && keys.length >= Object.keys(_proxyFormState).length) ||\n    keys.find(\n      (key) =>\n        _proxyFormState[key as keyof ReadFormState] ===\n        (!isRoot || VALIDATION_MODE.all),\n    )\n  );\n};\n","import type { FieldElement } from '../types';\n\nimport isCheckBoxInput from './isCheckBoxInput';\nimport isRadioInput from './isRadioInput';\n\nexport default (ref: FieldElement): ref is HTMLInputElement =>\n  isRadioInput(ref) || isCheckBoxInput(ref);\n","import compact from '../utils/compact';\nimport get from '../utils/get';\nimport unset from '../utils/unset';\n\nexport default <T>(ref: T, name: string) => {\n  const array = get(ref, name);\n\n  !compact(array).length &&\n    !(array as { root?: unknown })?.root &&\n    unset(ref, name);\n};\n","import type { ControllerProps, FieldPath, FieldValues } from './types';\nimport { useController } from './useController';\n\n/**\n * Component based on `useController` hook to work with controlled component.\n *\n * @remarks\n * [API](https://react-hook-form.com/docs/usecontroller/controller) • [Demo](https://codesandbox.io/s/react-hook-form-v6-controller-ts-jwyzw) • [Video](https://www.youtube.com/watch?v=N2UNk_UCVyA)\n *\n * @param props - the path name to the form field value, and validation rules.\n *\n * @returns provide field handler functions, field and form state.\n *\n * @example\n * ```tsx\n * function App() {\n *   const { control } = useForm<FormValues>({\n *     defaultValues: {\n *       test: \"\"\n *     }\n *   });\n *\n *   return (\n *     <form>\n *       <Controller\n *         control={control}\n *         name=\"test\"\n *         render={({ field: { onChange, onBlur, value, ref }, formState, fieldState }) => (\n *           <>\n *             <input\n *               onChange={onChange} // send value to hook form\n *               onBlur={onBlur} // notify when input is touched\n *               value={value} // return updated value\n *               ref={ref} // set ref for focus management\n *             />\n *             <p>{formState.isSubmitted ? \"submitted\" : \"\"}</p>\n *             <p>{fieldState.isTouched ? \"touched\" : \"\"}</p>\n *           </>\n *         )}\n *       />\n *     </form>\n *   );\n * }\n * ```\n */\nconst Controller = <\n  TFieldValues extends FieldValues = FieldValues,\n  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,\n  TTransformedValues = TFieldValues,\n>(\n  props: ControllerProps<TFieldValues, TName, TTransformedValues>,\n) =>\n  props.render(useController<TFieldValues, TName, TTransformedValues>(props));\n\nexport { Controller };\n","import { flatten } from './flatten';\n\nfunction jsonToFormData(json: any) {\n  const result = new FormData();\n\n  const flattenFormValues = flatten(json);\n\n  for (const key in flattenFormValues) {\n    result.append(key, flattenFormValues[key]);\n  }\n\n  return result;\n}\n\nexport { jsonToFormData };\n","function safeJSONStringify(value?: any) {\n  try {\n    return JSON.stringify(value);\n  } catch {\n    return '';\n  }\n}\n\nfunction safeJSONParse(value?: any) {\n  try {\n    return JSON.parse(value);\n  } catch {\n    return;\n  }\n}\n\nconst safeJSON = {\n  stringify: safeJSONStringify,\n  parse: safeJSONParse,\n};\n\nexport { safeJSON, safeJSONParse, safeJSONStringify };\n\nexport default safeJSON;\n","import type {\n  FieldPath,\n  FieldValues,\n  WatchProps,\n  WatchRenderValue,\n} from './types';\nimport { useWatch } from './useWatch';\n\n/**\n * Watch component that subscribes to form field changes and re-renders when watched fields update.\n *\n * @param control - The form control object from useForm\n * @param name - Can be field name, array of field names, or undefined to watch the entire form\n * @param disabled - Disable subscription\n * @param exact - Whether to watch exact field names or not\n * @param defaultValue - The default value to use if the field is not yet set\n * @param compute - Function to compute derived values from watched fields\n * @param render - The function that receives watched values and returns ReactNode\n * @returns The result of calling render function with watched values\n *\n * @example\n * The `Watch` component only re-render when the values of `foo`, `bar`, and `baz.qux` change.\n * The types of `foo`, `bar`, and `baz.qux` are precisely inferred.\n *\n * ```tsx\n * const { control } = useForm();\n *\n * <Watch\n *   control={control}\n *   names={['foo', 'bar', 'baz.qux']}\n *   render={([foo, bar, baz_qux]) => <div>{foo}{bar}{baz_qux}</div>}\n * />\n * ```\n */\nexport const Watch = <\n  TFieldValues extends FieldValues = FieldValues,\n  TFieldName extends\n    | FieldPath<TFieldValues>\n    | readonly [FieldPath<TFieldValues>, ...FieldPath<TFieldValues>[]]\n    | FieldPath<TFieldValues>[]\n    | readonly FieldPath<TFieldValues>[]\n    | undefined = undefined,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n  TComputeValue = undefined,\n>(\n  props: WatchProps<\n    TFieldName,\n    TFieldValues,\n    TContext,\n    TTransformedValues,\n    TComputeValue\n  >,\n) =>\n  props.render(\n    useWatch({ name: props.names, ...(props as any) }) as WatchRenderValue<\n      TFieldName,\n      TFieldValues,\n      TComputeValue\n    >,\n  );\n","import React from 'react';\n\nimport { DEFAULT_FORM_STATE } from './logic/createFormControl';\nimport getProxyFormState from './logic/getProxyFormState';\nimport cloneObject from './utils/cloneObject';\nimport deepEqual from './utils/deepEqual';\nimport isFunction from './utils/isFunction';\nimport { createFormControl } from './logic';\nimport type {\n  FieldValues,\n  FormState,\n  UseFormProps,\n  UseFormReturn,\n} from './types';\nimport { useIsomorphicLayoutEffect } from './useIsomorphicLayoutEffect';\nimport { useResyncOnReconnect } from './useResyncOnReconnect';\n\n/**\n * Custom hook to manage the entire form.\n *\n * @remarks\n * [API](https://react-hook-form.com/docs/useform) • [Demo](https://codesandbox.io/s/react-hook-form-get-started-ts-5ksmm) • [Video](https://www.youtube.com/watch?v=RkXv4AXXC_4)\n *\n * @param props - form configuration and validation parameters.\n *\n * @returns methods - individual functions to manage the form state. {@link UseFormReturn}\n *\n * @example\n * ```tsx\n * function App() {\n *   const { register, handleSubmit, watch, formState: { errors } } = useForm();\n *   const onSubmit = data => console.log(data);\n *\n *   console.log(watch(\"example\"));\n *\n *   return (\n *     <form onSubmit={handleSubmit(onSubmit)}>\n *       <input defaultValue=\"test\" {...register(\"example\")} />\n *       <input {...register(\"exampleRequired\", { required: true })} />\n *       {errors.exampleRequired && <span>This field is required</span>}\n *       <button>Submit</button>\n *     </form>\n *   );\n * }\n * ```\n */\nexport function useForm<\n  TFieldValues extends FieldValues = FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>(\n  props: UseFormProps<TFieldValues, TContext, TTransformedValues> = {},\n): UseFormReturn<TFieldValues, TContext, TTransformedValues> {\n  const _formControl = React.useRef<\n    UseFormReturn<TFieldValues, TContext, TTransformedValues> | undefined\n  >(undefined);\n  const _values = React.useRef<typeof props.values>(undefined);\n  const _formControlProp = React.useRef(props.formControl);\n  const [formState, updateFormState] = React.useState<FormState<TFieldValues>>(\n    () => ({\n      ...cloneObject(DEFAULT_FORM_STATE),\n      isLoading: isFunction(props.defaultValues),\n      errors: props.errors || {},\n      disabled: props.disabled || false,\n      defaultValues: isFunction(props.defaultValues)\n        ? undefined\n        : props.defaultValues,\n    }),\n  );\n\n  if (\n    !_formControl.current ||\n    (props.formControl && _formControlProp.current !== props.formControl)\n  ) {\n    _formControlProp.current = props.formControl;\n    if (props.formControl) {\n      _formControl.current = {\n        ...props.formControl,\n        formState,\n      };\n\n      if (props.defaultValues && !isFunction(props.defaultValues)) {\n        props.formControl.reset(props.defaultValues, props.resetOptions);\n      }\n    } else {\n      const { formControl, ...rest } = createFormControl(props);\n\n      _formControl.current = {\n        ...rest,\n        formState,\n      };\n    }\n  }\n\n  const control = _formControl.current.control;\n  control._options = props;\n\n  const { resyncIfNeeded, snapshot } =\n    useResyncOnReconnect<FormState<TFieldValues>>();\n\n  useIsomorphicLayoutEffect(() => {\n    const getCurrentFormState = () => ({\n      ...control._formState,\n      defaultValues:\n        control._defaultValues as FormState<TFieldValues>['defaultValues'],\n    });\n\n    resyncIfNeeded(true, getCurrentFormState, updateFormState);\n\n    const unsubscribe = control._subscribe({\n      formState: control._proxyFormState,\n      callback: () =>\n        updateFormState({\n          ...control._formState,\n          defaultValues:\n            control._defaultValues as FormState<TFieldValues>['defaultValues'],\n        }),\n      reRenderRoot: true,\n    });\n\n    updateFormState((data) => ({\n      ...data,\n      isReady: true,\n    }));\n\n    control._formState.isReady = true;\n\n    return () => {\n      unsubscribe();\n      snapshot(true, getCurrentFormState);\n    };\n  }, [control, resyncIfNeeded, snapshot]);\n\n  React.useEffect(\n    () => control._disableForm(props.disabled),\n    [control, props.disabled],\n  );\n\n  React.useEffect(() => {\n    if (props.mode) {\n      control._options.mode = props.mode;\n    }\n    if (props.reValidateMode) {\n      control._options.reValidateMode = props.reValidateMode;\n    }\n  }, [control, props.mode, props.reValidateMode]);\n\n  React.useEffect(() => {\n    if (props.errors) {\n      control._setErrors(props.errors);\n      control._focusError();\n    }\n  }, [control, props.errors]);\n\n  React.useEffect(() => {\n    props.shouldUnregister &&\n      control._subjects.state.next({\n        values: control._getWatch(),\n      });\n  }, [control, props.shouldUnregister]);\n\n  React.useEffect(() => {\n    if (control._proxyFormState.isDirty) {\n      const isDirty = control._getDirty();\n      if (isDirty !== formState.isDirty) {\n        control._subjects.state.next({\n          isDirty,\n        });\n      }\n    }\n  }, [control, formState.isDirty]);\n\n  React.useEffect(() => {\n    if (props.values && !deepEqual(props.values, _values.current)) {\n      control._reset(props.values, {\n        keepFieldsRef: true,\n        ...control._options.resetOptions,\n      });\n      if (!control._options.resetOptions?.keepIsValid) {\n        control._setValid();\n      }\n      _values.current = props.values;\n      updateFormState((state) => ({ ...state }));\n    } else {\n      control._resetDefaultValues();\n    }\n  }, [control, props.values]);\n\n  React.useEffect(() => {\n    if (!control._state.mount) {\n      control._setValid();\n      control._state.mount = true;\n    }\n\n    if (control._state.watch) {\n      control._state.watch = false;\n      control._subjects.state.next({ ...control._formState });\n    }\n\n    control._removeUnmounted();\n  });\n\n  _formControl.current.formState = React.useMemo(\n    () => getProxyFormState(formState, control),\n    [control, formState],\n  );\n\n  return _formControl.current;\n}\n"],"names":["isCheckBoxInput","element","type","isFileInput","isDateObject","value","Date","isNullOrUndefined","isObjectType","isObject","Array","isArray","getEventValue","event","target","checked","files","isNameInFieldArray","names","name","split","some","part","index","arr","isNaN","Number","has","slice","join","isPlainObject","tempObject","prototypeCopy","constructor","prototype","hasOwnProperty","isWeb","window","HTMLElement","document"